import { integer, maxLength, maxValue } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'text',
      type: 'formattedText',
      class: 'text-center mb-4',
      textType: 'text-subtitle-2',
      color: 'primaryColor',
      intl: true,
      value: 'starterLayout.editProfile.thirdStepText',
      oneLine: true,
    },
    {
      id: 'storeLogo',
      type: 'fileInput',
      accept: 'image/png, image/jpeg, image/bmp',
      label: 'starterLayout.editProfile.storeLogo',
      color: 'primaryColor',
      icon: 'mdi-image',
      oneLine: true,
    },
    {
      id: 'storetype',
      type: 'select',
      valueType: 'text',
      label: 'starterLayout.editProfile.storeType',
      items: state.storeTypes,
      itemText: 'name',
      color: 'primaryColor',
      oneLine: true,
    },
    {
      id: 'storeSize',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.storeSize',
      errorMessage: 'starterLayout.editProfile.integerTooLong',
      color: 'primaryColor',
      suffix: 'm²',
      validators: { integer, maxValue: maxValue(999) },
    },
    {
      id: 'coolersNumber',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.coolersNumber',
      errorMessage: 'starterLayout.editProfile.integerTooLong',
      color: 'primaryColor',
      validators: { integer, maxValue: maxValue(999) },
    },
    {
      id: 'secondText',
      type: 'formattedText',
      class: 'pt-0 pb-2',
      textType: 'text-subtitle-2',
      color: 'primaryColor',
      intl: true,
      value: 'starterLayout.editProfile.thirdStepText2',
      oneLine: true,
    },
    {
      id: 'installationType',
      type: 'input',
      valueType: 'text',
      label: 'starterLayout.editProfile.installationType',
      color: 'primaryColor',
      oneLine: true,
      validators: { maxLength: maxLength(20) },
      errorMessage: 'starterLayout.editProfile.installationTypeTooLong',
    },
  ],
  id: 'edit-profile-third-form',
})

export default setConfig
