<template>
  <DialogCard :config="dialogConfig.dialogData">
    <div class="loader-card">
      <v-img
        :src="require('@/assets/download-files.svg')"
        width="304"
        height="240"
      />
      <transition name="fade" mode="out-in">
        <FormattedText
          intl
          type="text-h6"
          :value="message"
          key="message"
          class="my-4"
        />
      </transition>
      <v-progress-linear :value="progressValue" />
    </div>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/AuthViews/SignUpProfileView/DownloadDialog/config'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'DownloadDialog',
  components: { DialogCard, FormattedText },
  props: {
    message: {
      type: String,
      required: true,
    },
    progressValue: {
      type: Number,
      required: true,
    },
  },
  computed: {
    ...mapState('app', ['downloadDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.downloadDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setDownloadDialogStatus]),
    closeDialog() {
      this[appActions.setDownloadDialogStatus](false)
    },
  },
}
</script>

<style lang="scss" scoped>
.loader-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 4em;
}
.fade-enter-active,
.fade-leave-active {
  transition: opacity 1s;
}

.fade-enter,
.fade-leave-to {
  opacity: 0;
}
</style>
