import {
  required,
  integer,
  maxLength,
  maxValue,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'text',
      type: 'formattedText',
      class: 'text-center mb-4',
      textType: 'text-subtitle-2',
      color: 'primaryColor',
      intl: true,
      value: 'starterLayout.editProfile.firstStepText',
      oneLine: true,
    },
    {
      id: 'storeName',
      type: 'input',
      valueType: 'text',
      oneLine: true,
      label: 'shared.storeName',
      errorMessage: 'starterLayout.editProfile.storeNameRequired',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: { required, maxLength: maxLength(95) },
    },
    {
      id: 'state',
      type: 'autocomplete',
      label: `starterLayout.editProfile.state${state.country}`,
      errorMessage: `starterLayout.editProfile.stateRequired${state.country}`,
      items: state.states,
      itemText: 'name',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
    {
      id: 'town',
      type: 'autocomplete',
      label: `starterLayout.editProfile.town${state.country}`,
      placeholder: `starterLayout.editProfile.townPlaceholder${state.country}`,
      errorMessage: `starterLayout.editProfile.townRequired${state.country}`,
      items: state.towns,
      color: 'primaryColor',
      required: true,
      readonly: state.towns && state.towns.length === 0,
      validators: { required },
    },
    {
      id: 'zipCode',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.zipCode',
      errorMessage: 'starterLayout.editProfile.zipCodeRequired',
      color: 'primaryColor',
      required: true,
      validators: { required, integer, maxValue: maxValue(999999999) },
    },
    {
      id: 'completeAddress',
      type: 'input',
      valueType: 'text',
      label: 'starterLayout.editProfile.completeAddress',
      errorMessage: 'starterLayout.editProfile.completeAddressRequired',
      color: 'primaryColor',
      required: true,
      validators: { required, maxLength: maxLength(95) },
    },
  ],
  id: 'edit-profile-first-form',
})

export default setConfig
