<template>
  <v-card class="dialog-style d-flex flex-column pb-4" height="680">
    <v-progress-linear
      class="progress"
      height="5"
      color="primary"
      :value="progress"
      v-if="progress > 0"
    />
    <v-card-title class="d-flex" :style="`background-color: #white;`">
      <v-icon class="pr-2" color="textPrimary">
        mdi-card-account-details
      </v-icon>
      <FormattedText
        type="text-h6"
        intl
        value="starterLayout.editProfile.title"
        color="textPrimary"
        class="title-text"
      />
    </v-card-title>
    <v-card-text class="fill-height">
      <v-stepper :value="currentStep" class="mt-0 stepper fill-height" flat>
        <v-stepper-header class="stepper__header">
          <v-stepper-step step="1" :complete="isFirstStepComplete">
            {{ getTranslatedText('starterLayout.editProfile.firstStep') }}
          </v-stepper-step>
          <v-divider></v-divider>
          <v-stepper-step step="2">
            {{ getTranslatedText('starterLayout.editProfile.secondStep') }}
            <small>{{ getTranslatedText('shared.optional') }}</small>
          </v-stepper-step>
          <v-divider></v-divider>
          <v-stepper-step step="3">
            {{ getTranslatedText('starterLayout.editProfile.thirdStep') }}
            <small>{{ getTranslatedText('shared.optional') }}</small>
          </v-stepper-step>
        </v-stepper-header>

        <v-stepper-items class="fill-height">
          <v-stepper-content step="1" class="pt-2 pb-0">
            <v-card class="pt-2" height="455">
              <Form :config="firstFormConfig" />
            </v-card>
          </v-stepper-content>
          <v-stepper-content step="2" class="pt-2 pb-0">
            <v-card class="pt-2" height="455">
              <Form :config="secondFormConfig" />
            </v-card>
          </v-stepper-content>
          <v-stepper-content step="3" class="pt-2 pb-0">
            <v-card class="pt-2" height="455">
              <Form :config="thirdFormConfig" />
            </v-card>
          </v-stepper-content>
        </v-stepper-items>
      </v-stepper>
    </v-card-text>
    <v-card-actions class="d-flex justify-end">
      <CustomButton
        className="mr-6"
        @click="previousButton"
        text="shared.previous"
        textType="text-subtitle-2"
        textClass="text-capitalize"
        intl
        color="accent"
        :disabled="isPreviousButtonDisabled"
      />
      <CustomButton
        className="mr-8"
        @click="continueButton"
        :text="continueButtonText"
        textType="text-subtitle-2"
        textClass="text-capitalize"
        intl
        :disabled="isContinueButtonDisabled"
      />
    </v-card-actions>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import storeTypes from '@/config/storeTypes'
import SIGNUP_EVENTS from '@/config/events/signUp'
import countries from '@/config/countries'

import { getTranslatedText, cleanObjectObserver } from '@/tools/data'
import { captureException } from '@/tools/exceptions'
import imageTools from '@/tools/image'

import rendererEventsService from '@/services/renderer/rendererEvents'

import accountActions from '@/store/account/actions.types'
import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import Form from '@/components/shared/Form2Columns'
import setFirstFormConfig from '@/components/AuthViews/SignUpProfileView/EditProfileCard/firstForm'
import setSecondFormConfig from '@/components/AuthViews/SignUpProfileView/EditProfileCard/secondForm'
import setThirdFormConfig from '@/components/AuthViews/SignUpProfileView/EditProfileCard/thirdForm'

export default {
  name: 'EditProfileCard',
  components: { FormattedText, CustomButton, Form },
  props: {
    progress: {
      type: Number,
      required: false,
      default: 0,
    },
  },
  data() {
    return {
      isContinueButtonDisabled: false,
      currentStep: 1,
      formsComplete: false,
      firstFormInputs: {},
      secondFormInputs: {},
      thirdFormInputs: {},
      validators: {
        firstFormInputs: {},
        secondFormInputs: {},
        thirdFormInputs: {},
      },
    }
  },
  computed: {
    ...mapState('app', ['ready', 'countrySelected']),
    ...mapState('account', {
      accountRegistered: state => state.data.account,
      fetching: state => state.fetching,
      securityData: state => state.data.security,
      country: state => state.data.country,
      userName: state => state.data.name,
      restoreError: state => state.error,
    }),
    states() {
      return countries[this.countrySelected.toString()].states
    },
    towns() {
      return countries[this.countrySelected.toString()].getTowns(
        this.firstFormInputs.state
      )
    },
    firstFormConfig() {
      return setFirstFormConfig(
        {
          inputs: this.firstFormInputs,
          v: this.$v.firstFormInputs,
          country: this.countrySelected.toString(),
          states: this.states,
          towns: this.towns,
        },
        {}
      )
    },
    secondFormConfig() {
      return setSecondFormConfig(
        {
          inputs: this.secondFormInputs,
          v: this.$v.secondFormInputs,
          accountRegistered: this.accountRegistered.toString(),
          userName: this.userName,
        },
        {}
      )
    },
    thirdFormConfig() {
      return setThirdFormConfig(
        {
          inputs: this.thirdFormInputs,
          v: this.$v.thirdFormInputs,
          storeTypes:
            this.country.localeIsoCode in storeTypes
              ? storeTypes[this.country.localeIsoCode]
              : storeTypes['default'],
        },
        {}
      )
    },
    isPreviousButtonDisabled() {
      return this.currentStep === 1
    },
    continueButtonText() {
      return this.currentStep === 3 ? 'shared.finish' : 'shared.continue'
    },
    isFirstStepComplete() {
      return this.currentStep > 1
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('account', [
      accountActions.setFetching,
      accountActions.setOwnerAndStoreNames,
      accountActions.setAccountLoginError,
    ]),
    ...mapActions('app', [appActions.setDownloadDialogStatus]),
    previousButton() {
      if (this.currentStep === 1) return
      this.currentStep -= 1
    },
    continueButton() {
      if (this.currentStep === 3) {
        this.isContinueButtonDisabled = true
        if (this.$v.thirdFormInputs.$invalid) {
          Object.keys(this.thirdFormInputs).forEach(key => {
            if (this.$v.thirdFormInputs[key])
              this.$v.thirdFormInputs[key].$touch()
          })
          this.isContinueButtonDisabled = false
          return
        }
        this.formsComplete = true
      } else {
        if (this.currentStep === 1 && this.$v.firstFormInputs.$invalid) {
          Object.keys(this.firstFormInputs).forEach(key => {
            if (this.$v.firstFormInputs[key])
              this.$v.firstFormInputs[key].$touch()
          })
          return
        } else if (
          this.currentStep === 2 &&
          this.$v.secondFormInputs.$invalid
        ) {
          Object.keys(this.secondFormInputs).forEach(key => {
            if (this.$v.secondFormInputs[key])
              this.$v.secondFormInputs[key].$touch()
          })
          return
        }
        this.currentStep += 1
      }
    },
    async submitFormsData() {
      this[accountActions.setFetching](true)
      const imageResult = await imageTools.compress(
        this.thirdFormInputs.storeLogo
      )
      const imageBase64 = imageResult ? imageResult.dataUrl.split(',')[1] : null
      delete this.thirdFormInputs.storeLogo
      rendererEventsService.send(SIGNUP_EVENTS.channel, {
        event: SIGNUP_EVENTS.events.confirmProfile.name,
        data: {
          inputs: {
            imageBase64,
            ...this.firstFormInputs,
            ...this.secondFormInputs,
            ...this.thirdFormInputs,
          },
          securityData: this.securityData,
          country: this.country.phoneCode,
        },
      })
    },
    setProperties() {
      this.firstFormConfig.fields.forEach(field => {
        const isVisible = Object.hasOwn(field, 'visible') ? field.visible : true
        const isHidden = Object.hasOwn(field, 'hideCol') ? field.hideCol : false
        if (isVisible && !isHidden) {
          !isNil(field.defaultValue)
            ? this.$set(this.firstFormInputs, field.id, field.defaultValue)
            : field.type === 'fileInput'
            ? this.$set(this.firstFormInputs, field.id, undefined)
            : this.$set(this.firstFormInputs, field.id, '')
          if (field.validators)
            this.$set(this.validators.firstFormInputs, field.id, {
              ...cleanObjectObserver(field.validators),
            })
        }
      })
      this.secondFormConfig.fields.forEach(field => {
        !isNil(field.defaultValue)
          ? this.$set(this.secondFormInputs, field.id, field.defaultValue)
          : field.type === 'fileInput'
          ? this.$set(this.secondFormInputs, field.id, undefined)
          : this.$set(this.secondFormInputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.secondFormInputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
      this.thirdFormConfig.fields.forEach(field => {
        !isNil(field.defaultValue)
          ? this.$set(this.thirdFormInputs, field.id, field.defaultValue)
          : field.type === 'fileInput'
          ? this.$set(this.thirdFormInputs, field.id, undefined)
          : this.$set(this.thirdFormInputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.thirdFormInputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
  },
  validations() {
    return this.validators
  },
  watch: {
    'firstFormInputs.state': function(newValue, oldValue) {
      if (this.firstFormInputs.state === null) {
        this.firstFormInputs.state = ''
        this.firstFormInputs.town = ''
      } else if (
        this.firstFormInputs.state &&
        this.firstFormInputs.state !== ''
      ) {
        if (this.towns) {
          this.firstFormInputs.town =
            oldValue === '' ? this.firstFormInputs.town : ''
        }
      }
    },
    formsComplete(newFormsCompleteValue) {
      if (newFormsCompleteValue === true) {
        this.submitFormsData()
        if (this.ready === true) return
        if (this.restoreError) {
          this.$router
            .push({ name: 'UnfinishedRestore' })
            .catch(error => captureException(error))
        } else {
          this[appActions.setDownloadDialogStatus](true)
        }
      }
    },
    ready(newReadyValue) {
      if (newReadyValue === true && this.formsComplete === true) {
        this.submitFormsData()
      }
    },
  },
  mounted() {
    this.setProperties()
    rendererEventsService.subscribe(
      SIGNUP_EVENTS.replyChannel,
      async (event, payload) => {
        const signupReplies = SIGNUP_EVENTS.events.confirmProfile.replies
        const replies = {
          [signupReplies.success]: () => {
            if (this.ready === false) return
            this[accountActions.setOwnerAndStoreNames]({
              storeName: this.firstFormInputs.storeName,
              ownerName: this.secondFormInputs.name,
              storeImage: payload.data.storeImage,
              storeAddress: this.firstFormInputs.completeAddress,
              storePostalCode: this.firstFormInputs.zipCode,
              storeCity: this.firstFormInputs.city
                ? this.firstFormInputs.city
                : '',
              storeTown: this.firstFormInputs.town,
              storeState: this.firstFormInputs.state,
              storeLandlinePhone: this.secondFormInputs.landlinePhone,
              storePhone: this.secondFormInputs.storePhone,
            })
            this.$track({
              type: 'system',
              action: 'response',
              category: 'SignupProfile',
              screen: 'ConfirmProfile',
              name: 'Open store',
            })
            this[accountActions.setFetching](false)
            this[appActions.setDownloadDialogStatus](false)
            this.$router.push({ name: 'OpenRegister' })
          },
          [signupReplies.error]: () => {
            this[accountActions.setOwnerAndStoreNames]({
              storeName: this.firstFormInputs.storeName,
              ownerName: this.secondFormInputs.name,
              storeImage: '',
              storeAddress: this.firstFormInputs.completeAddress,
              storePostalCode: this.firstFormInputs.zipCode,
              storeCity: this.firstFormInputs.city
                ? this.firstFormInputs.city
                : '',
              storeTown: this.firstFormInputs.town,
              storeState: this.firstFormInputs.state,
              storeLandlinePhone: this.secondFormInputs.landlinePhone,
              storePhone: this.secondFormInputs.storePhone,
            })
            this.$track({
              type: 'system',
              action: 'error',
              category: 'SignupProfile',
              screen: 'ConfirmProfile',
              name: 'Open store',
            })
            this[accountActions.setFetching](false)
            this[appActions.setDownloadDialogStatus](false)
            this.$router.push({ name: 'OpenRegister' })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
}
</script>

<style lang="scss" scoped>
.dialog-style {
  border-bottom-left-radius: 8px;
  border-bottom-right-radius: 8px;
  .title-text {
    font-family: Lato, Helvetica, Roboto, Arial, sans-serif;
  }
}
.stepper {
  box-shadow: none !important;
  .stepper__header {
    box-shadow: none !important;
  }
}
.progress {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
}
</style>
