import {
  required,
  integer,
  maxLength,
  maxValue,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'text',
      type: 'formattedText',
      class: 'text-center mb-4',
      textType: 'text-subtitle-2',
      color: 'primaryColor',
      intl: true,
      value: 'starterLayout.editProfile.secondStepText',
      oneLine: true,
    },
    {
      id: 'email',
      type: 'input',
      valueType: 'text',
      label: 'starterLayout.signUp.email',
      color: 'primaryColor',
      oneLine: true,
      readonly: state.accountRegistered.includes('@') ? true : false,
      validators: { maxLength: maxLength(95) },
      defaultValue: state.accountRegistered.includes('@')
        ? state.accountRegistered
        : '',
    },
    {
      id: 'name',
      type: 'input',
      valueType: 'text',
      label: 'shared.ownerName',
      errorMessage: 'starterLayout.editProfile.ownerNameTooLong',
      color: 'primaryColor',
      oneLine: true,
      validators: { maxLength: maxLength(95) },
      defaultValue:
        state.userName.includes(state.accountRegistered) ||
        state.userName.toLowerCase() === state.accountRegistered
          ? ''
          : state.userName,
    },
    {
      id: 'storePhone',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'shared.phone',
      errorMessage: 'starterLayout.editProfile.mobilePhoneRequired',
      color: 'primaryColor',
      oneLine: true,
      required: true,
      readonly: state.accountRegistered.includes('@') ? false : true,
      validators: { required, integer, maxValue: maxValue(99999999999) },
      defaultValue: state.accountRegistered.includes('@')
        ? ''
        : state.accountRegistered,
    },
    {
      id: 'landlinePhone',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'shared.landlinePhone',
      errorMessage: 'starterLayout.editProfile.landlinePhoneTooLong',
      color: 'primaryColor',
      oneLine: true,
      validators: { integer, maxValue: maxValue(99999999999) },
    },
  ],
  id: 'edit-profile-second-form',
})

export default setConfig
