<template>
  <transition appear name="fade">
    <v-container fill-height class="login">
      <v-row class="text-center">
        <v-col cols="12" class="pt-0">
          <v-row align="center" justify="center">
            <v-col align="center" justify="center" class="pt-0">
              <SignUpHeader />
            </v-col>
          </v-row>
        </v-col>
        <v-col cols="12" class="pt-0 mb-2">
          <v-row align="center" justify="center">
            <v-col align="center" justify="center" class="pt-0">
              <EditProfileCard class="login" :progress="progressValue" />
            </v-col>
          </v-row>
        </v-col>
        <v-col cols="12" class="py-0">
          <v-row align="center" justify="center">
            <v-col align="center" class="py-0">
              <SignUpFooter />
            </v-col>
          </v-row>
        </v-col>
      </v-row>
      <DownloadDialog
        v-if="downloadDialog.isOpen"
        :message="message"
        :progressValue="progressValue"
      />
    </v-container>
  </transition>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { values, isEmpty } from 'ramda'

import { ytTutorialTiendatek } from '@/config/env'
import RESTORE_EVENTS from '@/config/events/restore'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import DIAGNOSTIC_EVENTS from '@/config/events/diagnostic'
import AIRTIME_API_EVENTS from '@/config/events/airtime'
import YOUTUBE_API_EVENTS from '@/config/events/youtube'
import { PROCEDENCE_REGISTER } from '@/config/pushTokenProcedence'
import WHATSAPP_TEMPLATES_API_EVENTS from '@/config/events/serversAPI/whatsappTemplates'

import { checkIfAllObjectPropsAreTrue } from '@/tools/data'
import { captureException } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'
import pushNotificationsService from '@/services/renderer/pushNotifications'

import accountActions from '@/store/account/actions.types'
import appActions from '@/store/app/actions.types'
import usersActions from '@/store/users/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import productsActions from '@/store/products/actions.types'
import customersActions from '@/store/customers/actions.types'
import suppliersActions from '@/store/suppliers/action.types'
import vendorsActions from '@/store/vendors/actions.types'
import airtimeServicesActions from '@/store/airtimeServices/actions.types'
import helpCenterActions from '@/store/helpCenter/actions.types'
import whatsappTemplatesActions from '@/store/whatsappTemplates/actions.types'

import SignUpHeader from '@/components/AuthViews/Header'
import SignUpFooter from '@/components/AuthViews/Footer'
import EditProfileCard from '@/components/AuthViews/SignUpProfileView/EditProfileCard'
import DownloadDialog from '@/components/AuthViews/SignUpProfileView/DownloadDialog'

export default {
  name: 'SignUpProfile',
  components: {
    SignUpHeader,
    SignUpFooter,
    EditProfileCard,
    DownloadDialog,
  },
  data() {
    return {
      message: 'appInitialization.initializing',
      restoring: false,
      progressValue: 0,
      starterStatus: {
        products: false,
        customers: false,
        suppliers: false,
        vendors: false,
        airtimeServicesBanks: false,
        youtubeVideos: false,
        whatsappTemplates: false,
      },
    }
  },
  computed: {
    ...mapState('app', ['ready', 'downloadDialog']),
    ...mapState('account', ['data', 'fetching']),
    ...mapState('helpCenter', { tutorials: state => state.data.videos }),
  },
  methods: {
    ...mapActions('account', [
      accountActions.setFetching,
      accountActions.setAccountLoginError,
    ]),
    ...mapActions('app', [
      appActions.setReady,
      appActions.setDownloadDialogStatus,
    ]),
    ...mapActions('users', [usersActions.getUsers]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    ...mapActions('products', [
      productsActions.fetchProducts,
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.setProductsOrSuperCategoriesError,
    ]),
    ...mapActions('customers', [
      customersActions.fetchCustomers,
      customersActions.setCustomersFetching,
      customersActions.setCustomersError,
    ]),
    ...mapActions('suppliers', values(suppliersActions)),
    ...mapActions('vendors', values(vendorsActions)),
    ...mapActions('airtimeServices', [airtimeServicesActions.setBanks]),
    ...mapActions('helpCenter', [
      helpCenterActions.fetchVideos,
      helpCenterActions.setVideoFetching,
      helpCenterActions.setVideoError,
    ]),
    ...mapActions('whatsappTemplates', [
      whatsappTemplatesActions.setWhatsappTemplates,
    ]),
  },
  watch: {
    starterStatus: {
      deep: true,
      handler() {
        const isStartterProcessOk = checkIfAllObjectPropsAreTrue(
          this.starterStatus
        )
        if (isStartterProcessOk) {
          rendererEventsService.send(DIAGNOSTIC_EVENTS.channel, {
            event: DIAGNOSTIC_EVENTS.events.checkDatabase.name,
          })
        }
      },
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      RESTORE_EVENTS.replyChannel,
      (event, payload) => {
        this.restoring = true
        const replies = {
          [RESTORE_EVENTS.events.restoreProcess.replies.start]: () => {
            this.message = 'appInitialization.initializing'
          },
          [RESTORE_EVENTS.events.restoreProcess.replies.mlpDownload]: () => {
            this.message = 'appInitialization.downloadingMlp'
            this.progressValue = payload.data.progress
          },
          [RESTORE_EVENTS.events.restoreProcess.replies.restoreProcess]: () => {
            this.message = 'appInitialization.settingUpStore'
            this.progressValue = payload.data.progress
          },
          [RESTORE_EVENTS.events.restoreProcess.replies.assets]: () => {
            this.message = 'appInitialization.downloadingAssets'
            this.progressValue = payload.data.progress
          },
          [RESTORE_EVENTS.events.restoreProcess.replies.error]: () => {
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Signup',
              screen: 'RestoreProcess',
              name: 'Error with restore process',
            })
            this.restoring = false
            this[accountActions.setAccountLoginError](payload)
            if (this.downloadDialog.isOpen) {
              this[appActions.setDownloadDialogStatus](false)
              this.$router
                .push({ name: 'UnfinishedRestore' })
                .catch(error => captureException(error))
            }
          },
          [RESTORE_EVENTS.events.restoreProcess.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'api_call',
              category: 'Signup',
              screen: 'RestoreProcess',
              name: 'Restore finished',
            })
            this.message = 'appInitialization.settingUpStore'
            this.progressValue = payload.data.progress
            setTimeout(() => {
              this.message = 'appInitialization.justMoment'
            }, 1500)
            setTimeout(() => {
              this[usersActions.getUsers](payload.data.users)
              this[usersViewActions.setSelectedUser](payload.data.selectedUser)
              this[productsActions.setProductsOrSuperCategoriesFetching](true)
              rendererEventsService.send(ENTITIES_EVENTS.channel, {
                event: ENTITIES_EVENTS.events.getAllByEntities.name,
                data: {
                  entitiesToGet: [
                    'storeInventory',
                    'superCategories',
                    'genericCategories',
                    'byWeightHomeCodes',
                    'airtimeProviders',
                    'airtimeServices',
                  ],
                  replyName: 'fetchProducts',
                },
              })
              this[customersActions.setCustomersFetching](true)
              rendererEventsService.send(ENTITIES_EVENTS.channel, {
                event: ENTITIES_EVENTS.events.getAllByEntities.name,
                data: {
                  entitiesToGet: ['sales', 'customers', 'receivables'],
                  replyName: 'fetchCustomers',
                },
              })
              this[suppliersActions.setSuppliersFetching](true)
              rendererEventsService.send(ENTITIES_EVENTS.channel, {
                event: ENTITIES_EVENTS.events.getAllByEntities.name,
                data: {
                  entitiesToGet: ['suppliers'],
                  replyName: 'fetchSuppliers',
                },
              })
              this[vendorsActions.setVendorsFetching](true)
              rendererEventsService.send(ENTITIES_EVENTS.channel, {
                event: ENTITIES_EVENTS.events.getAllByEntities.name,
                data: {
                  entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
                  replyName: 'fetchVendors',
                },
              })
              rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
                event: AIRTIME_API_EVENTS.events.fetchBanks.name,
                data: {
                  token: this.data.security.token,
                },
              })
              rendererEventsService.send(
                WHATSAPP_TEMPLATES_API_EVENTS.channel,
                {
                  event:
                    WHATSAPP_TEMPLATES_API_EVENTS.events.getWhatsappTemplates
                      .name,
                  data: {
                    token: this.data.security.token,
                  },
                }
              )
              if (isEmpty(this.tutorials)) {
                this[helpCenterActions.setVideoFetching](true)
                rendererEventsService.send(YOUTUBE_API_EVENTS.channel, {
                  event: YOUTUBE_API_EVENTS.events.getPlaylist.name,
                  data: {
                    playlistId: ytTutorialTiendatek,
                  },
                })
              } else {
                this.starterStatus = {
                  ...this.starterStatus,
                  youtubeVideos: true,
                }
              }
              pushNotificationsService.startService(PROCEDENCE_REGISTER)
              this[accountActions.setFetching](false)
            }, 2000)
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )

    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      async (event, payload) => {
        const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
        const replies = {
          [`${getAllReplies.success}-fetchProducts`]: () => {
            this[productsActions.fetchProducts](payload.data)
            this.starterStatus = { ...this.starterStatus, products: true }
          },
          [`${getAllReplies.success}-fetchCustomers`]: () => {
            this[customersActions.fetchCustomers](payload.data)
            this.starterStatus = { ...this.starterStatus, customers: true }
          },
          [`${getAllReplies.success}-fetchSuppliers`]: () => {
            this[suppliersActions.setSuppliers](payload.data)
            this.starterStatus = { ...this.starterStatus, suppliers: true }
          },
          [`${getAllReplies.success}-fetchVendors`]: () => {
            this[vendorsActions.setVendors](payload.data)
            this.starterStatus = { ...this.starterStatus, vendors: true }
          },
          [`${getAllReplies.error}-fetchProducts`]: () => {
            this[productsActions.setProductsOrSuperCategoriesError](
              payload.data
            )
            this[productsActions.setProductsOrSuperCategoriesFetching](false)
          },
          [`${getAllReplies.error}-fetchCustomers`]: () => {
            this[customersActions.setCustomersError](payload.data)
            this[customersActions.setCustomersFetching](false)
          },
          [`${getAllReplies.error}-fetchSuppliers`]: () => {
            this[suppliersActions.setSuppliersError](payload.data)
            this[suppliersActions.setSuppliersFetching](false)
          },
          [`${getAllReplies.error}-fetchVendors`]: () => {
            this[vendorsActions.setVendorsError](payload.data)
            this[vendorsActions.setVendorsFetching](false)
          },
        }
        if (payload.event in replies) replies[payload.event]()
        const regex = new RegExp(`^${getAllReplies.error}-([\\w-]+)$`)
        const match = payload.event.match(regex)
        if (match) {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Signup',
            screen: 'FetchEntities',
            name: `Error ${match[1]}`,
          })
        }
      }
    )
    rendererEventsService.subscribe(
      DIAGNOSTIC_EVENTS.replyChannel,
      async (event, payload) => {
        const diagnosticReplies = DIAGNOSTIC_EVENTS.events.checkDatabase.replies
        const replies = {
          [diagnosticReplies.success]: () => {
            this.message = 'appInitialization.accountCreatedAndReady'
            this.restoring = false
            this[appActions.setReady](true)
          },
          [diagnosticReplies.error]: () => {},
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )

    rendererEventsService.subscribe(
      AIRTIME_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AIRTIME_API_EVENTS.events.fetchBanks.replies.success]: () => {
            this[airtimeServicesActions.setBanks](payload.data.banks)
            this.starterStatus = {
              ...this.starterStatus,
              airtimeServicesBanks: true,
            }
          },
          [AIRTIME_API_EVENTS.events.fetchBanks.replies.error]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              airtimeServicesBanks: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel,
      async (event, payload) => {
        const whatsappEvents = WHATSAPP_TEMPLATES_API_EVENTS.events
        const replies = {
          [whatsappEvents.getWhatsappTemplates.replies.success]: () => {
            this[whatsappTemplatesActions.setWhatsappTemplates](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              whatsappTemplates: true,
            }
          },
          [whatsappEvents.getWhatsappTemplates.replies.error]: () => {
            this.starterStatus = {
              ...this.starterStatus,
              whatsappTemplates: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      YOUTUBE_API_EVENTS.replyChannel,
      async (event, payload) => {
        const ytReplies = YOUTUBE_API_EVENTS.events.getPlaylist.replies
        const replies = {
          [`${ytReplies.success}`]: () => {
            this[helpCenterActions.fetchVideos](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              youtubeVideos: true,
            }
          },
          [`${ytReplies.error}`]: () => {
            this[helpCenterActions.setVideoError](payload.data)
            this.starterStatus = {
              ...this.starterStatus,
              youtubeVideos: true,
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(RESTORE_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(ENTITIES_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(DIAGNOSTIC_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(AIRTIME_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(YOUTUBE_API_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(
      WHATSAPP_TEMPLATES_API_EVENTS.replyChannel
    )
  },
}
</script>

<style>
.fade-enter {
  opacity: 0;
}

.fade-enter-active {
  transition: opacity 2s ease-out;
}
.login {
  width: 900px;
}
</style>
